ON CONFLICT (course_id, campus_id, academic_unit_id, academic_term_id) DO UPDATE SET credits_snapshot = EXCLUDED.credits_snapshot, weekly_hours_snapshot = EXCLUDED.weekly_hours_snapshot, course_type = EXCLUDED.course_type, is_active = TRUE, deactivated_at = NULL, updated_at = NOW();
UPDATE public.course_offering AS t
SET
  weekly_hours_snapshot = nv.weekly_hours_snapshot::INTEGER,
  is_active = TRUE,
  deactivated_at = NULL,
  updated_at = NOW()
FROM (VALUES
  (3403, 6),
  (7770, 6)
) AS nv (id, weekly_hours_snapshot)
WHERE t.id = nv.id::BIGINT;
UPDATE public.course_offering AS t
SET
  course_type = nv.course_type::TEXT,
  is_active = TRUE,
  deactivated_at = NULL,
  updated_at = NOW()
FROM (VALUES
  (4741, E'TRABAJO FINAL DE GRADUACION'),
  (3578, E'TRABAJO FINAL DE GRADUACION'),
  (6553, E'TRABAJO FINAL DE GRADUACION')
) AS nv (id, course_type)
WHERE t.id = nv.id::BIGINT;
UPDATE public.course_offering SET is_active = FALSE, deactivated_at = NOW(), updated_at = NOW() WHERE id = ANY(ARRAY[7830]::BIGINT[]) AND academic_term_id = ANY(ARRAY[3, 6, 21, 22, 23, 24, 25, 26, 27, 40, 41, 42, 43, 44, 45, 52, 53, 54, 59, 60, 85, 86, 87, 88, 89, 90, 91, 92, 93, 94, 95, 96, 101, 102, 111, 112, 113, 114, 117]::BIGINT[]);

